import {loadFont} from '@remotion/fonts';
import {staticFile} from 'remotion';

// Subset fonts generated by scripts/subset-fonts.py (Noto Sans TC + JetBrains Mono, OFL).
const faces: [string, string, string][] = [
  ['NotoTC', 'fonts/NotoSansTC-Regular.woff2', '400'],
  ['NotoTC', 'fonts/NotoSansTC-Medium.woff2', '500'],
  ['NotoTC', 'fonts/NotoSansTC-Bold.woff2', '700'],
  ['NotoTC', 'fonts/NotoSansTC-Black.woff2', '900'],
  ['JBMono', 'fonts/JetBrainsMono-Regular.woff2', '400'],
  ['JBMono', 'fonts/JetBrainsMono-SemiBold.woff2', '600'],
];
export const fontsReady = Promise.all(
  faces.map(([family, file, weight]) => loadFont({family, url: staticFile(file), weight})),
);
